import static org.junit.jupiter.api.Assertions.*;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import org.apache.parquet.format.EncryptionAlgorithm;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class InternalFileDecryptorSetFileCryptoMetaDataTests {

  @Test
  void initializesFileAadForAesGcmWithoutPrefixAndAllowsMatchingReuse() {
    byte[] fileUnique = new byte[] {1, 2, 3, 4};
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(fileUnique);

    InternalFileDecryptor decryptor = newDecryptor(null);

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertTrue(booleanField(decryptor, "fileCryptoMetaDataProcessed"));
    assertArrayEquals(fileUnique, byteField(decryptor, "fileAAD"));

    decryptor.setFileCryptoMetaData(algorithm, false, null);
    assertArrayEquals(fileUnique, byteField(decryptor, "fileAAD"));
  }

  @Test
  void combinesFilePrefixAndFileUniqueComponent() {
    byte[] prefix = new byte[] {9, 8};
    byte[] fileUnique = new byte[] {1, 2, 3};
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(fileUnique);
    invokeSetter(algorithmComponent(algorithm, "AES_GCM_V1"), "setAad_prefix", prefix);

    InternalFileDecryptor decryptor = newDecryptor(null);

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    byte[] expected = new byte[] {9, 8, 1, 2, 3};
    assertArrayEquals(expected, byteField(decryptor, "fileAAD"));
  }

  @Test
  void supportsAesGcmCtrAlgorithm() {
    byte[] fileUnique = new byte[] {4, 5, 6};
    EncryptionAlgorithm algorithm = newAlgorithmComponent("AES_GCM_CTR_V1", fileUnique);

    InternalFileDecryptor decryptor = newDecryptor(null);

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(fileUnique, byteField(decryptor, "fileAAD"));
  }

  @Test
  void rejectsUnsupportedAlgorithm() {
    InternalFileDecryptor decryptor = newDecryptor(null);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(new EncryptionAlgorithm(), false, null));
  }

  @Test
  void rejectsReuseWithDifferentFooterEncryptionFlag() {
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(new byte[] {1, 2});

    InternalFileDecryptor decryptor = newDecryptor(null);
    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, true, null));
  }

  @Test
  void rejectsReuseWithDifferentFooterKeyMetadata() {
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(new byte[] {1, 2});

    InternalFileDecryptor decryptor = newDecryptor(null);
    decryptor.setFileCryptoMetaData(algorithm, false, new byte[] {7});

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, new byte[] {8}));
  }

  @Test
  void rejectsMissingRequiredExternalAadPrefix() {
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(new byte[] {1});
    Object aesGcm = algorithmComponent(algorithm, "AES_GCM_V1");
    invokeSetter(aesGcm, "setSupply_aad_prefix", true);

    InternalFileDecryptor decryptor = newDecryptor(null);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  @Test
  void rejectsPrefixPropertiesWhenFileDoesNotUsePrefix() {
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(new byte[] {1, 2});

    InternalFileDecryptor decryptor = newDecryptor(new byte[] {9});

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  private static InternalFileDecryptor newDecryptor(byte[] aadPrefix) {
    FileDecryptionProperties.Builder builder = FileDecryptionProperties.builder()
        .withFooterKey(new byte[16]);
    if (aadPrefix != null) {
      builder.withAADPrefix(aadPrefix);
    }
    return new InternalFileDecryptor(builder.build());
  }

  private static EncryptionAlgorithm aesGcmAlgorithm(byte[] fileUnique) {
    return newAlgorithmComponent("AES_GCM_V1", fileUnique);
  }

  private static EncryptionAlgorithm newAlgorithmComponent(
      String setterName, byte[] fileUnique) {
    try {
      Method setter = Arrays.stream(EncryptionAlgorithm.class.getMethods())
          .filter(method -> method.getName().equals("set" + setterName))
          .filter(method -> method.getParameterCount() == 1)
          .findFirst()
          .orElseThrow(() -> new AssertionError("Missing algorithm setter " + setterName));

      Class<?> componentType = setter.getParameterTypes()[0];
      Object component = componentType.getDeclaredConstructor().newInstance();
      invokeSetter(
          component,
          "setAad_file_unique",
          Arrays.copyOf(fileUnique, fileUnique.length));

      EncryptionAlgorithm algorithm = new EncryptionAlgorithm();
      setter.invoke(algorithm, component);
      return algorithm;
    } catch (ReflectiveOperationException e) {
      throw new AssertionError("Unable to create encryption algorithm", e);
    }
  }

  private static Object algorithmComponent(EncryptionAlgorithm algorithm, String setterName) {
    try {
      Field field = Arrays.stream(EncryptionAlgorithm.class.getDeclaredFields())
          .filter(candidate -> candidate.getName().equals(lowerFirst(setterName)))
          .findFirst()
          .orElseThrow(() -> new AssertionError("Missing algorithm field " + setterName));
      field.setAccessible(true);
      return field.get(algorithm);
    } catch (ReflectiveOperationException e) {
      throw new AssertionError("Unable to inspect encryption algorithm", e);
    }
  }

  private static void invokeSetter(Object target, String name, Object value) {
    try {
      Method setter = Arrays.stream(target.getClass().getMethods())
          .filter(method -> method.getName().equals(name))
          .filter(method -> method.getParameterCount() == 1)
          .filter(method -> isCompatible(method.getParameterTypes()[0], value))
          .findFirst()
          .orElseThrow(() -> new AssertionError("Missing compatible setter " + name));
      setter.invoke(target, value);
    } catch (ReflectiveOperationException e) {
      throw new AssertionError("Unable to invoke setter " + name, e);
    }
  }

  private static boolean isCompatible(Class<?> parameterType, Object value) {
    if (value == null) {
      return !parameterType.isPrimitive();
    }
    if (!parameterType.isPrimitive()) {
      return parameterType.isInstance(value);
    }
    return (parameterType == boolean.class && value instanceof Boolean)
        || (parameterType == byte.class && value instanceof Byte)
        || (parameterType == short.class && value instanceof Short)
        || (parameterType == int.class && value instanceof Integer)
        || (parameterType == long.class && value instanceof Long)
        || (parameterType == float.class && value instanceof Float)
        || (parameterType == double.class && value instanceof Double)
        || (parameterType == char.class && value instanceof Character);
  }

  private static String lowerFirst(String value) {
    return Character.toLowerCase(value.charAt(0)) + value.substring(1);
  }

  private static boolean booleanField(Object target, String name) {
    try {
      Field field = target.getClass().getDeclaredField(name);
      field.setAccessible(true);
      return field.getBoolean(target);
    } catch (ReflectiveOperationException e) {
      throw new AssertionError("Unable to inspect field " + name, e);
    }
  }

  private static byte[] byteField(Object target, String name) {
    try {
      Field field = target.getClass().getDeclaredField(name);
      field.setAccessible(true);
      return (byte[]) field.get(target);
    } catch (ReflectiveOperationException e) {
      throw new AssertionError("Unable to inspect field " + name, e);
    }
  }
}

