    byte[] fileUnique = new byte[] {7, 8, 9};
    EncryptionAlgorithm algorithm = encryptionAlgorithm(null, fileUnique, false);

    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(decryptionPropertiesWithFooterKey());

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(fileUnique, privateByteArray(decryptor, "fileAAD"));
