    decryptor.setFileCryptoMetaData(algorithm, false, new byte[] {10, 11});
    decryptor.setFileCryptoMetaData(algorithm, false, new byte[] {10, 11});

    assertArrayEquals(new byte[] {2}, privateByteArray(decryptor, "fileAAD"));
    assertEquals(algorithm, privateValue(decryptor, "algorithm"));
