    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(decryptionPropertiesWithFooterKey());

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(unsupported, false, null));
  }

