    return FileDecryptionProperties.builder()
        .withFooterKey(new byte[16])
        .build();
  }

  private static EncryptionAlgorithm encryptionAlgorithm(
      byte[] aadPrefix, byte[] fileUnique, boolean supplyPrefix) {
    AesGcmV1 aesGcmV1 = new AesGcmV1();
    aesGcmV1.setAad_file_unique(fileUnique);
    aesGcmV1.setSupply_aad_prefix(supplyPrefix);
    if (aadPrefix != null) {
      aesGcmV1.setAad_prefix(aadPrefix);
    }

    EncryptionAlgorithm algorithm = new EncryptionAlgorithm();
    algorithm.setAES_GCM_V1(aesGcmV1);
    return algorithm;
  }

  private static byte[] privateByteArray(Object target, String fieldName) throws Exception {
    Object value = privateValue(target, fieldName);
    return value == null ? null : Arrays.copyOf((byte[]) value, ((byte[]) value).length);
  }

  private static Object privateValue(Object target, String fieldName) throws Exception {
    Field field = target.getClass().getDeclaredField(fieldName);
    field.setAccessible(true);
    return field.get(target);
  }
