    // Helper methods to create EncryptionAlgorithm instances

    private EncryptionAlgorithm createAesGcmV1Algorithm(boolean hasAadPrefix, boolean mustSupplyAadPrefix, 
                                                         byte[] aadPrefix, byte[] aadFileUnique) {
        AesGcmV1 aesGcmV1 = new AesGcmV1();
        if (hasAadPrefix && aadPrefix != null) {
            aesGcmV1.setAad_prefix(aadPrefix);
        }
        aesGcmV1.setSupply_aad_prefix(mustSupplyAadPrefix);
        if (aadFileUnique != null) {
            aesGcmV1.setAad_file_unique(aadFileUnique);
        }
        return EncryptionAlgorithm.AES_GCM_V1(aesGcmV1);
    }

    private EncryptionAlgorithm createAesGcmCtrV1Algorithm(boolean hasAadPrefix, boolean mustSupplyAadPrefix, 
                                                            byte[] aadPrefix, byte[] aadFileUnique) {
        AesGcmCtrV1 aesGcmCtrV1 = new AesGcmCtrV1();
        if (hasAadPrefix && aadPrefix != null) {
            aesGcmCtrV1.setAad_prefix(aadPrefix);
        }
        aesGcmCtrV1.setSupply_aad_prefix(mustSupplyAadPrefix);
        if (aadFileUnique != null) {
            aesGcmCtrV1.setAad_file_unique(aadFileUnique);
        }
        return EncryptionAlgorithm.AES_GCM_CTR_V1(aesGcmCtrV1);
    }
